import pandas as pd
import os

files = ['ERP-2025-table10.xls', 'ERP-2025-table12.xls', 'CPI.xlsx']

for file in files:
    print(f"--- Inspecting {file} ---")
    try:
        if file.endswith('.xls'):
            # try reading with 'xlrd' first, if fails might need 'openpyxl' or just engine='xlrd'
            # Note: newer xlrd versions don't support xlsx, but these are xls.
            df = pd.read_excel(file, nrows=10) # Inspect first few rows
        else:
            df = pd.read_excel(file, nrows=10)
        print(df.head(10))
    except Exception as e:
        print(f"Error reading {file}: {e}")
    print("\n")
